import { inject, type InjectionKey } from 'vue';
import type { ToggleSize, ToggleVariant } from '../toggle/Toggle.vue';

export type ToggleGroupStyleContextValue = {
  size: () => ToggleSize;
  variant: () => ToggleVariant;
};

const defaultToggleGroupStyleContext: ToggleGroupStyleContextValue = {
  size: () => 'md',
  variant: () => 'default',
};

export const ToggleGroupStyleContextKey: InjectionKey<ToggleGroupStyleContextValue> =
  Symbol('ToggleGroupStyleContext');

export const useToggleGroupStyleContext = () =>
  inject(ToggleGroupStyleContextKey, defaultToggleGroupStyleContext);

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    max-inline-size: 100%;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
    --moduix-toggle-color: var(--moduix-toggle-group-color, var(--moduix-color-foreground));
    gap: var(--moduix-toggle-group-gap, var(--moduix-border-width-sm));
    padding: var(--moduix-toggle-group-padding, var(--moduix-border-width-md));
    border: var(--moduix-toggle-group-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-toggle-group-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-toggle-group-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-toggle-group-bg, var(--moduix-color-muted));
    color: var(--moduix-toggle-group-color, var(--moduix-color-foreground));

    &::-webkit-scrollbar {
      display: none;
    }

    &[data-orientation='vertical'] {
      flex-direction: column;
      align-items: stretch;

      & > .item {
        width: 100%;
        justify-content: flex-start;
      }
    }

    &[data-variant='ghost'] {
      padding: var(--moduix-toggle-group-padding, var(--moduix-toggle-group-ghost-padding, 0));
      border-color: var(
        --moduix-toggle-group-border-color,
        var(--moduix-toggle-group-ghost-border-color, transparent)
      );
      background-color: var(
        --moduix-toggle-group-bg,
        var(--moduix-toggle-group-ghost-bg, transparent)
      );
    }

    &[data-variant='outline'] {
      background-color: var(
        --moduix-toggle-group-bg,
        var(--moduix-toggle-group-outline-bg, var(--moduix-color-background))
      );
    }
  }

  .item {
    flex: 0 0 auto;
    border-radius: var(--moduix-toggle-group-item-radius, var(--moduix-radius-md));
  }
}

import {
  ToggleGroupContext,
  useToggleGroup,
  useToggleGroupContext,
} from '@ark-ui/vue/toggle-group';
import ToggleGroup from './ToggleGroup.vue';
import ToggleGroupItem from './ToggleGroupItem.vue';
import ToggleGroupRootProvider from './ToggleGroupRootProvider.vue';

export {
  ToggleGroup,
  ToggleGroupContext,
  ToggleGroupItem,
  ToggleGroupRootProvider,
  useToggleGroup,
  useToggleGroupContext,
};

export type {
  ToggleGroupContextProps,
  ToggleGroupItemBaseProps,
  ToggleGroupRootBaseProps,
  ToggleGroupRootEmits,
  ToggleGroupRootProviderBaseProps,
  ToggleGroupValueChangeDetails,
  UseToggleGroupContext,
  UseToggleGroupProps,
  UseToggleGroupReturn,
} from '@ark-ui/vue/toggle-group';

export type { ToggleGroupItemProps } from './ToggleGroupItem.vue';
export type { ToggleGroupRootProps } from './ToggleGroup.vue';
export type { ToggleGroupRootProviderProps } from './ToggleGroupRootProvider.vue';
export type { ToggleSize, ToggleVariant } from '../toggle/Toggle.vue';
